package com.yihe.framework.ehr;
import java.util.*;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.support.TransactionTemplate;import static com.yihe.framework.ehr.EhrAccess.*;import static com.yihe.framework.ehr.EhrService.*;
@SuppressWarnings("unchecked") public class PsychologicalAssessmentChecks {
 static class Fake extends DigitalWorkerModelClient{Map<String,Object>input;public Map<String,Object>status(){return map("configured",true);}public Map<String,Object>generate(Map<String,Object>x){input=x;return map("output","隔离心理测评流程检查，不作实际诊断或心理结论。");}}
 static void check(String n,boolean ok){if(!ok)throw new AssertionError(n);System.out.println("PASS "+n);}static void reject(String n,int c,Runnable f){try{f.run();throw new AssertionError(n);}catch(EhrException e){check(n,e.status==c);}}
 static Map<String,Object> register(String id){return map("recordId",id,"requestKey",EhrService.id(),"category","stress","instrument","隔离流程量表，不用于实际测评","measuredAt",java.time.LocalDateTime.now().minusHours(1).withSecond(0).withNano(0).toString(),"score",12,"maxScore",40,"note","合成流程验证，无临床含义","sourceDescription","隔离夹具，事务结束回滚","sourceVerified",true);}
 static Map<String,Object> request(String r){return map("records",Arrays.asList(r),"year",2026,"requestKey",id());}
 public static void main(String[]args){if(!System.getenv("EHR_JDBC_URL").contains("/shayu_3_preview?"))throw new IllegalArgumentException("preview only");DriverManagerDataSource ds=new DriverManagerDataSource(System.getenv("EHR_JDBC_URL"),System.getenv("EHR_DB_USER"),System.getenv("EHR_DB_PASSWORD"));EhrRepository db=new EhrRepository(ds);EhrService ehr=new EhrService(db);Fake model=new Fake();PsychologicalAssessmentService s=new PsychologicalAssessmentService(db,ehr,new EmployeeHealthArchiveService(db,ehr),model);PsychologicalAssessmentWorker w=new PsychologicalAssessmentWorker(s,model);Map<String,Object>u=db.one("SELECT user_code,Org_Code org FROM yh_user_reginfo WHERE user_code='LOCAL-PREVIEW' AND User_Type=4 AND lock_flag=2");EhrActor a=new EhrActor(str(u.get("user_code")),str(u.get("org")),"synthetic",true,false),reader=new EhrActor(a.user,str(u.get("org")),"synthetic",false,false),other=new EhrActor(a.user,"PSY_OTHER","synthetic",true,false);new TransactionTemplate(new DataSourceTransactionManager(ds)).execute(tx->{try{Map<String,Object>defaults=s.settings.defaults("assess");defaults.put("version",s.settings.get(a,"assess").get("version"));s.settings.save(a,"assess",defaults);OcrRosterIdentityChecks.Fixture f=ArchiveReviewChecks.fixture(db,ehr,a,true);String original=ehr.encode(ehr.profile(a,f.record,false)),report=ehr.encode(ehr.snapshot(f.report,1));Map<String,Object>initial=s.list(a,new HashMap<>());check("physical_roster_is_not_psychological_measurement",num(((Map<?,?>)initial.get("counts")).get("participants"))==0);check("questionnaire_rate_is_unknown_without_delivery_stats",((Map<?,?>)initial.get("counts")).get("completionRate")==null);reject("non_doctor_cannot_read_sensitive_measurements",403,()->s.list(reader,new HashMap<>()));reject("other_unit_cannot_read_person",404,()->s.detail(other,f.record,2026,null));reject("somatic_report_cannot_start_psychological_analysis",422,()->s.enqueue(a,request(f.record)));Map<String,Object>b=register(f.record),bad=new LinkedHashMap<>(b);bad.put("score",41);reject("score_cannot_exceed_declared_max",422,()->s.register(a,bad));bad.put("score",12);bad.put("sourceVerified",false);reject("registration_requires_real_source_verification",422,()->s.register(a,bad));s.register(a,b);s.register(a,b);check("registration_is_idempotent",db.count("SELECT COUNT(*) FROM a_psych_measurements WHERE record_id=?",f.record)==1);bad.put("sourceVerified",true);bad.put("instrument","changed");reject("registration_key_cannot_change_content",409,()->s.register(a,bad));Map<String,Object>list=s.list(a,new HashMap<>());check("participant_and_record_counts_come_from_measurements",num(((Map<?,?>)list.get("counts")).get("participants"))==1&&num(list.get("recordTotal"))==1);check("no_automatic_psychological_grade",num(((Map<?,?>)list.get("counts")).get("confirmed"))==0);Map<String,Object>req=request(f.record);s.enqueue(a,req);s.enqueue(a,req);check("analysis_batch_replay",db.count("SELECT COUNT(*) FROM a_psych_assessment_tasks WHERE record_id=?",f.record)==1);Map<String,Object>t=s.claim("synthetic");String tid=str(t.get("task_id"));w.process(t);check("model_only_receives_registered_measurements",((Map<?,?>)model.input.get("archive_context")).containsKey("measurements")&&!((Map<?,?>)model.input.get("archive_context")).containsKey("person"));check("specialized_psychological_policy_selected","psychological_assessment".equals(model.input.get("task_type")));Map<String,Object>job=(Map<String,Object>)s.detail(a,f.record,2026,null).get("job");check("ai_does_not_assign_attention_level","unknown".equals(job.get("risk_level")));Map<String,Object>domains=new LinkedHashMap<>();for(String fct:PsychologicalAssessmentService.FACTORS)domains.put(fct,map("level","unknown","basis",""));domains.put("stress",map("level","medium","basis","隔离来源核对，不适用于真实心理风险"));Map<String,Object>rev=map("action","review","requestKey",id(),"version",job.get("row_version"),"riskLevel","medium","domains",domains,"note","隔离专业审核流程验证","identityVerified",true,"sourceVerified",false);reject("review_requires_original_measurement_verification",422,()->s.action(a,tid,rev));rev.put("sourceVerified",true);long ledger=db.count("SELECT COUNT(*) FROM a_health_risk_assessments");s.action(a,tid,rev);s.action(a,tid,rev);check("mental_grade_does_not_change_somatic_risk_ledger",ledger==db.count("SELECT COUNT(*) FROM a_health_risk_assessments"));Map<String,Object>after=s.list(a,new HashMap<>());check("attention_distribution_uses_professional_confirmation",num(((Map<?,?>)after.get("counts")).get("medium"))==1);check("record_category_grade_is_confirmed_domain",((List<Map<String,Object>>)after.get("records")).stream().anyMatch(m->m.get("riskLevel").equals("medium")));check("physical_roster_unchanged",original.equals(ehr.encode(ehr.profile(a,f.record,false))));check("somatic_report_unchanged",report.equals(ehr.encode(ehr.snapshot(f.report,1))));check("twelve_month_trace_exists",((List<?>)after.get("trend")).size()==12);s.register(a,register(f.record));check("new_measurement_invalidates_old_analysis",Boolean.TRUE.equals(s.detail(a,f.record,2026,null).get("sourceChanged")));check("old_grades_not_counted_as_current",num(((Map<?,?>)s.list(a,new HashMap<>()).get("counts")).get("confirmed"))==0);s.enqueue(a,request(f.record));Map<String,Object>cancel=s.claim("synthetic");s.action(a,str(cancel.get("task_id")),map("action","cancel","requestKey",id(),"version",cancel.get("row_version"),"note","隔离取消"));s.finish(cancel,"late",null);check("cancelled_result_not_committed","cancelled".equals(((Map<?,?>)s.detail(a,f.record,2026,null).get("job")).get("ai_state")));reject("unsupported_category_rejected",422,()->s.list(a,Collections.singletonMap("category","invented")));check("other_org_tasks_empty",s.tasks(other).isEmpty());}finally{tx.setRollbackOnly();w.stop();}return null;});}
}
